idx=s.find(anchor)
if idx<0: raise SystemExit('web motorOcpdFactor anchor not found')
helpers=r'''function motorGroupRow(k,flc){const type=`mm${k}_type`,dev=`mm${k}_dev`,duty=`mm${k}_duty`,rating=`mm${k}_rating`;return `<div class="card" style="padding:10px;margin:8px 0"><b>Motor ${k}</b><div class="grid">${field('FLC A',`mm${k}_flc`,flc,'text')}${select('Motor / starting type',type,['Single-phase AC — all types','Squirrel-cage / synchronous — full-voltage, resistor or reactor','Squirrel-cage / synchronous — autotransformer or star-delta','Wound-rotor AC','DC motor'],'Squirrel-cage / synchronous — full-voltage, resistor or reactor')}${select('Branch OCPD type',dev,['Time-delay fuse','Non-time-delay fuse','Inverse-time circuit breaker'],'Time-delay fuse')}${select('Duty class',duty,['Continuous','Short-time','Intermittent','Periodic','Varying'],'Continuous')}${select('Duty rating',rating,['5 min','15 min','30/60 min','Continuous rating'],'5 min')}</div></div>`}
function motorDutyFactor(duty,rating){if(duty==='Continuous')return 1.0;if(duty==='Short-time'){if(rating==='5 min')return 1.10;if(rating==='15 min')return 1.20;if(rating==='30/60 min')return 1.50;throw new Error('Short-time duty does not use the continuous-rating column')}if(duty==='Intermittent')return rating==='5 min'||rating==='15 min'?.85:rating==='30/60 min'?.90:1.40;if(duty==='Periodic')return rating==='5 min'?.85:rating==='15 min'?.90:rating==='30/60 min'?.95:1.40;if(duty==='Varying')return rating==='5 min'?1.10:rating==='15 min'?1.20:rating==='30/60 min'?1.50:2.00;throw new Error('Select a motor duty class')}
function collectMotorGroup(){const motors=[];for(let k=1;k<=6;k++){const raw=s(`mm${k}_flc`).trim();if(!raw)continue;const flc=parseFloat(raw);if(!Number.isFinite(flc)||flc<=0)throw new Error(`Check Motor ${k} FLC`);const type=s(`mm${k}_type`),device=s(`mm${k}_dev`),duty=s(`mm${k}_duty`),rating=s(`mm${k}_rating`),continuous=duty==='Continuous',dc=type==='DC motor';motors.push({flc,continuous,dutyFactor:continuous?1:motorDutyFactor(duty,rating),branchOcpdFactor:motorOcpdFactor(type,device,flc,null,0,dc),motorType:type,deviceType:motorOcpdDeviceCode(device)})}if(!motors.length)throw new Error('Enter at least one motor');return motors}
function calcMultiMotorDetailed(){return post(`/api/calculators/multi-motor-detailed`,{motors:collectMotorGroup(),simultaneousStartExtra:n(`mm_extra`),conductorMaterial:s(`mm_mat`)==='Aluminum'?'ALUMINUM':'COPPER'},`o_mm`)}
function calcMotorSplitterTap(){const duty=s(`mt_duty`),continuous=duty==='Continuous',len=s(`mt_len`).startsWith('2')?2:s(`mt_len`).startsWith('5')?5:n(`mt_custom`);return post(`/api/calculators/motor-splitter-tap`,{motorFlc:n(`mt_flc`),continuous,dutyFactor:continuous?1:motorDutyFactor(duty,s(`mt_rating`)),feederAmpacity:n(`mt_feeder`),tapLengthM:len,enclosedInMetal:b(`mt_metal`),mechanicallyProtected:b(`mt_mech`),conductorMaterial:s(`mt_mat`)==='Aluminum'?'ALUMINUM':'COPPER'},`o_mt`)}
'''
s=s[:idx]+helpers+s[idx:]
p.write_text(s)
